// 使用宿主四语资源模拟产品界面；系统采样、文件和更新全部使用受控样例。
const $=id=>document.getElementById(id),media=matchMedia('(prefers-color-scheme:dark)');
const names=['DotNet','Aurora','Ember','Default','Aquatic','Desert','Dusk','NightSky'];
// 标题色点对齐共享 StudioSwatch 资源；界面明暗变化不改变色点本身。
const titleSwatches={DotNet:'#512BD4',Aurora:'linear-gradient(135deg,#8968FF,#26D4CC)',Ember:'#BD674D',Default:'#0064FA',Aquatic:'#008D9E',Desert:'#B57532',Dusk:'#7A5CC4',NightSky:'#2B6CB0'};
const cultures=[['zh-CN','SimplifiedChinese'],['zh-Hant','TraditionalChinese'],['en-US','English'],['ja-JP','Japanese']];
let culture='zh-CN',mode='system',palette='DotNet',route='process',tab='appearance',processTab='overview',state='idle',timer,remember=false,paused=false,selectedPid=6408;
const processes=[{pid:6408,name:'NexusDash',cpu:'2.1%',memory:'124 MB',publisher:'CodeWF',network:true,user:true,system:false},{pid:5120,name:'dotnet',cpu:'12.8%',memory:'846 MB',publisher:'Microsoft',network:true,user:false,system:true},{pid:3216,name:'Code',cpu:'4.2%',memory:'612 MB',publisher:'Microsoft',network:false,user:true,system:false}];
const processFilters=new Set();
function visibleProcesses(){const query=$('search').value.toLowerCase();return processes.filter(item=>(!query||[item.name,item.pid,item.publisher].join(' ').toLowerCase().includes(query))&&(!processFilters.has('FilterHasNetworkConnections')||item.network)&&(!processFilters.has('FilterHighCpu')||parseFloat(item.cpu)>=5)&&(!processFilters.has('FilterUserProcesses')||item.user)&&(!processFilters.has('FilterHideSystemProcesses')||!item.system));}
try{const saved=JSON.parse(localStorage.getItem('nexusdash-appearance')||'{}');if(cultures.some(item=>item[0]===saved.culture))culture=saved.culture;if(['system','light','dark'].includes(saved.mode))mode=saved.mode;if(names.includes(saved.palette))palette=saved.palette;remember=!!saved.remember;}catch{}
const t=(key,...args)=>{const value=(window.translations[culture]||window.translations['en-US'])[key];if(value===undefined)throw Error('Missing resource '+key);return value.replace(/\{(\d+)(?::[^}]+)?\}/g,(_,index)=>args[+index]??'{'+index+'}');};
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function persist(){try{localStorage.setItem('nexusdash-appearance',JSON.stringify({culture,mode,palette,remember}));}catch{}}
function theme(){const dark=mode==='dark'||mode==='system'&&media.matches;for(const[k,v]of Object.entries(window.palettes[palette][dark?'dark':'light']))document.documentElement.style.setProperty('--'+k,v);Object.assign(document.documentElement.dataset,{theme:dark?'dark':'light',mode,palette,route,tab});document.documentElement.style.colorScheme=dark?'dark':'light';persist();}
function text(){document.documentElement.lang=culture;const themeButton=$('theme-cycle');themeButton.textContent=({system:'▣',light:'☀',dark:'☾'})[mode];themeButton.title=t('ThemeMenu')+': '+t({system:'ThemeSystem',light:'LightTheme',dark:'DarkTheme'}[mode]);themeButton.setAttribute('aria-label',themeButton.title);$('language-button').title=t('LanguageMenu');$('language-button').setAttribute('aria-label',t('LanguageMenu'));document.querySelectorAll('#title-swatches button').forEach(button=>{button.classList.toggle('selected',button.dataset.palette===palette);button.setAttribute('aria-pressed',button.dataset.palette===palette);button.title=t((['DotNet','Aurora','Ember','Default'].includes(button.dataset.palette)?'Palette':'Theme')+button.dataset.palette);button.setAttribute('aria-label',button.title);});document.querySelectorAll('#title-language-menu button').forEach(button=>{button.textContent=t(cultures.find(item=>item[0]===button.dataset.culture)[1]);button.setAttribute('aria-checked',button.dataset.culture===culture);});document.querySelectorAll('[data-key]').forEach(el=>el.textContent=t(el.dataset.key));document.querySelectorAll('[data-placeholder]').forEach(el=>el.placeholder=t(el.dataset.placeholder));$('status').textContent=t(paused?'StatusPaused':'StatusRunning');$('selection-count').textContent=t('StatusSelected',selectedPid?1:0);$('pause').textContent=paused?'▶':'Ⅱ';$('pause').title=t(paused?'Resume':'Pause');$('pause').setAttribute('aria-label',$('pause').title);$('log').textContent='14:27:19 '+t('LogMessage','14:27:19',t('LogApplicationStarted'));}
const graph=index=>`<svg class="chart" viewBox="0 0 400 160" preserveAspectRatio="none" aria-hidden="true"><line x1="0" y1="30" x2="400" y2="30"/><line x1="0" y1="70" x2="400" y2="70"/><line x1="0" y1="110" x2="400" y2="110"/><line x1="0" y1="150" x2="400" y2="150"/><path d="M0 ${140-index*18} L45 110 80 125 120 60 160 100 200 50 250 80 300 60 350 85 400 ${40+index*12}"/></svg>`;
function appearance(){return `<div class="form"><div class="form-row"><label for="mode">${t('ThemeMenu')}</label><select id="mode">${[['system','ThemeSystem'],['light','LightTheme'],['dark','DarkTheme']].map(([id,key])=>`<option value="${id}">${t(key)}</option>`).join('')}</select></div><div class="form-row"><label for="palette">${t('PaletteLabel')}</label><div class="palette-field"><span class="palette-dot"></span><select id="palette">${names.map(name=>`<option value="${name}">${t((['DotNet','Aurora','Ember','Default'].includes(name)?'Palette':'Theme')+name)}</option>`).join('')}</select></div></div><div class="form-row languages"><span>${t('LanguageMenu')}</span><div role="radiogroup" aria-label="${t('LanguageMenu')}">${cultures.map(([value,key])=>`<label><input type="radio" name="language" value="${value}" ${culture===value?'checked':''}>${t(key)}</label>`).join('')}</div></div><div class="form-row remember"><label for="remember">${t('RememberWindowSize')}</label><input id="remember" type="checkbox" ${remember?'checked':''}></div></div>`;}
function about(){return `<div class="about"><div class="about-head"><img src="../../logo.png" alt=""><div><h2>NexusDash</h2><p>${t('AboutDescription')}</p></div></div><dl>${[['AboutVersion','0.1.11'],['AboutCompileTime','2026-10-15 00:00:00'],['AboutAuthor',t('AboutAuthorName')],['AboutRepository','https://github.com/dotnet9/NexusDash'],['AboutLicense','MIT'],['AboutCopyright','Copyright © 2026 CodeWF'],['AboutPlatform','.NET 10.0.11 · Avalonia 12.1.4.0']].map(([key,value])=>`<dt>${t(key)}</dt><dd>${key==='AboutRepository'?`<button class="repository-link">${value}</button>`:value}</dd>`).join('')}</dl><div class="update"><b>${t('UpdateCheck')}</b><p>${t('AboutUpdateDescription')}</p><div class="update-actions"><button id="action"></button><button id="recheck" hidden>${t('AboutRecheck')}</button><button id="cancel" hidden>${t('AboutCancel')}</button></div><progress id="progress" value="0" max="100" hidden></progress><p id="update-status" role="status"></p></div></div>`;}
function settings(){return '<div class="settings"><div class="settings-nav">'+[['appearance','SettingsAppearance'],['changelog','SettingsChangelog'],['about','SettingsAbout']].map(([id,key])=>`<button data-tab="${id}" class="${tab===id?'selected':''}">${t(key)}</button>`).join('')+'</div><div class="settings-page">'+(tab==='appearance'?appearance():tab==='about'?about():`<div class="changelog"><h2>${t('SettingsChangelog')}</h2><div class="tabs"><button class="selected">${t('ChangelogChinese')}</button><button>${t('ChangelogEnglish')}</button></div><h3>0.1.11</h3><ul><li>${t('PaletteLabel')} · 8</li><li>${t('LanguageMenu')} · 4</li><li>${t('UpdateCheck')}</li></ul></div>` )+'</div></div>';}
function processView(){
 const tabs='<div class="tabs">'+[['overview','ProcessOverview'],['tree','ProcessTree'],['treemap','Treemap']].map(([value,key])=>`<button data-process-tab="${value}" class="${processTab===value?'selected':''}">${t(key)}</button>`).join('')+'</div>';
 if(processTab==='overview')return tabs+'<div class="cards">'+[['Cpu','34.0%',t('TopCpuProcess','dotnet','12.8')],['Memory','62.0%',t('TopMemoryProcess','dotnet','846 MB')],['Disk','2.1 MB/s',t('TopDiskProcess','Code','1.8 MB/s')],['Network','8.4 MB/s',t('TopNetworkConnections','NexusDash',3)]].map(([key,value,hint],index)=>`<div class="card metric-${index}"><div class="metric-heading"><h3>${t(key)}</h3><div class="metric">${value}</div></div>${graph(index)}${index===0?'<progress max="100" value="34"></progress>':index===1?'<span>19.84 GB / 32.00 GB</span>':''}<span>${hint}</span></div>`).join('')+'</div>';
 if(processTab==='treemap')return tabs+`<div class="treemap">${processes.map((item,index)=>`<button data-pid="${item.pid}" style="grid-column:span ${index===0?1:2}"><b>${item.name}</b><span>${item.memory}</span></button>`).join('')}</div>`;
 return tabs+`<div class="process-explorer"><div class="process-table"><div class="filter-row">${['FilterHasNetworkConnections','FilterHighCpu','FilterUserProcesses','FilterHideSystemProcesses'].map(key=>`<label><input type="checkbox" data-filter="${key}" ${processFilters.has(key)?'checked':''}>${t(key)}</label>`).join('')}</div><table><thead><tr>${['ProcessName','Pid','Cpu','Memory','Publisher'].map(key=>`<th>${t(key)}</th>`).join('')}</tr></thead><tbody>${visibleProcesses().map(item=>`<tr data-pid="${item.pid}" class="${selectedPid===item.pid?'selected':''}"><td>▸ ${item.name}</td><td>${item.pid}</td><td>${item.cpu}</td><td>${item.memory}</td><td>${item.publisher}</td></tr>`).join('')}</tbody></table><button id="end-process">${t('EndProcess')}</button></div><div class="process-details"><div class="tabs">${['Details','Handles','Network','Services','Startup'].map((key,index)=>`<button data-detail="${key}" class="${index===0?'selected':''}">${t(key)}</button>`).join('')}</div><div id="detail-content">${processDetail('Details')}</div></div></div>`;
}
function processDetail(key){const item=processes.find(item=>item.pid===selectedPid);if(!item)return t('NoProcessSelected');if(key==='Details')return `<dl>${[['ProcessName',item.name],['Pid',item.pid],['Publisher',item.publisher],['Path','C:/Apps/'+item.name+'.exe'],['CommandLine',item.name+' --sample'],['StartTime','2026-10-15 14:27:19']].map(([key,value])=>`<dt>${t(key)}</dt><dd>${value}</dd>`).join('')}</dl>`;return `<p>${t({Handles:'HandlesUnavailable',Network:'NetworkNoConnections',Services:'ServicesUnavailable',Startup:'StartupUnavailable'}[key])}</p>`;}
const samples=[['README.md','C:/Projects/NexusDash','12 KB'],['UpdateLog.md','C:/Projects/NexusDash','8 KB'],['MainWindow.axaml','C:/Projects/NexusDash/src','6 KB']];
let fileResults=[],searching=false,searchTimer,query='',roots='C:/Projects';
function filesView(){return `<div class="file-search"><div class="search-panel"><div><input id="file-query" value="${escape(query)}" placeholder="${t('FileSearchPlaceholder')}"><button id="find">${t('FileSearchButton')}</button><button id="cancel-search" ${searching?'':'hidden'}>${t('FileSearchCancel')}</button></div><div><label for="file-root">${t('FileSearchLocation')}</label><input id="file-root" value="${escape(roots)}" placeholder="${t('FileSearchRootPlaceholder')}"></div></div><div class="search-results"><header><b>${t('FileSearch')}</b><span>${t('FileSearchResultCount',fileResults.length)}</span></header><table><thead><tr>${['FileSearchName','FileSearchDirectory','FileSearchFullPath','FileSearchType','FileSearchSize','FileSearchModified'].map(key=>`<th>${t(key)}</th>`).join('')}</tr></thead><tbody>${fileResults.map(([name,directory,size])=>`<tr><td>${name}</td><td>${directory}</td><td>${directory}/${name}</td><td>${t('FileSearchFile')}</td><td>${size}</td><td>2026-10-15</td></tr>`).join('')}</tbody></table>${fileResults.length?'':`<p class="empty">${t(query?'FileSearchNoResults':'FileSearchStatusReady')}</p>`}</div></div>`;}
function hardwareView(){return `<div class="hardware-head"><div><h2>${t('HardwareInfo')}</h2><p>${t('HardwareStatusLoaded',3)}</p><small>${t('HardwareLastUpdated','14:27:19')}</small></div><button id="refresh-hardware">${t('HardwareRefresh')}</button></div><div class="hardware-sections">${[['HardwareOverview',[['HardwareOperatingSystem','Windows 11'],['HardwareArchitecture','x64'],['HardwareRuntime','.NET 10.0.11']]],['HardwareProcessor',[['HardwareCpuName','AMD Ryzen 7'],['HardwarePhysicalCores','8'],['HardwareLogicalProcessors','16']]],['HardwareMemory',[['HardwareTotalMemory','32 GB'],['HardwareAvailableMemory','12.16 GB'],['HardwareMemorySlots','2 / 4']]]].map(([title,rows])=>`<section><h3>${t(title)}</h3><dl>${rows.map(([key,value])=>`<dt>${t(key)}</dt><dd>${value}</dd>`).join('')}</dl></section>`).join('')}</div>`;}
function render(){theme();document.querySelectorAll('#nav [data-route]').forEach(el=>el.classList.toggle('selected',el.dataset.route===route));$('page').innerHTML=route==='process'?processView():route==='settings'?settings():route==='files'?filesView():hardwareView();text();$('export').hidden=route!=='process';$('pause').hidden=route!=='process';document.querySelectorAll('button[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;render();});document.querySelectorAll('[data-process-tab]').forEach(el=>el.onclick=()=>{processTab=el.dataset.processTab;render();});
 if($('mode')){$('mode').value=mode;$('palette').value=palette;$('mode').onchange=e=>{mode=e.target.value;theme();};$('palette').onchange=e=>{palette=e.target.value;theme();};document.querySelectorAll('input[name=language]').forEach(el=>el.onchange=()=>{culture=el.value;render();});$('remember').onchange=e=>{remember=e.target.checked;persist();};}
 if($('action')){$('action').onclick=advance;$('cancel').onclick=()=>{clearTimeout(timer);state='canceled';update();};$('recheck').onclick=()=>{state='idle';advance();};document.querySelector('.repository-link').onclick=()=>toast('https://github.com/dotnet9/NexusDash');update();}
 document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{el.checked?processFilters.add(el.dataset.filter):processFilters.delete(el.dataset.filter);render();});
 document.querySelectorAll('[data-pid]').forEach(el=>el.onclick=()=>{selectedPid=+el.dataset.pid;render();});document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>{document.querySelectorAll('[data-detail]').forEach(button=>button.classList.toggle('selected',button===el));$('detail-content').innerHTML=processDetail(el.dataset.detail);});
 if($('end-process'))$('end-process').onclick=()=>{if(!selectedPid)return;$('confirm-message').textContent=t('ConfirmEndProcessMessage',1);$('confirm-dialog').showModal();};
 if($('file-query')){$('file-query').oninput=e=>query=e.target.value;$('file-root').oninput=e=>roots=e.target.value;$('find').onclick=()=>{if(!query.trim()){toast(t('FileSearchEmptyQuery'));return;}if(!roots.trim()){toast(t('FileSearchRootsUnavailable'));return;}searching=true;render();$('status').textContent=t('FileSearchStatusSearching',query);searchTimer=setTimeout(()=>{searching=false;fileResults=samples.filter(row=>row[0].toLowerCase().includes(query.toLowerCase().replaceAll('*','')));render();$('status').textContent=t('FileSearchStatusCompleted',fileResults.length,query);},300);};$('cancel-search').onclick=()=>{clearTimeout(searchTimer);searching=false;render();$('status').textContent=t('FileSearchStatusCancelled');};}
 if($('refresh-hardware'))$('refresh-hardware').onclick=()=>{toast(t('HardwareStatusLoading'));setTimeout(()=>toast(t('HardwareStatusLoaded',3)),200);};
}
function update(){const busy=['checking','downloading'].includes(state);$('action').disabled=busy;$('cancel').hidden=!busy;$('progress').hidden=state!=='downloading';$('recheck').hidden=!['available','downloaded','installed'].includes(state);$('action').textContent=t(state==='available'?(window.updateScenario==='noasset'?'UpdateReleasePage':'UpdateDownload'):state==='downloaded'?'UpdateInstall':'UpdateCheck');$('update-status').textContent=state==='idle'?'':state==='available'?t('AboutAvailable','0.2.0'):state==='failed'?t('AboutFailed','offline'):t({checking:'AboutChecking',current:'AboutCurrent',downloading:'AboutDownloading',downloaded:'AboutDownloaded',canceled:'AboutCanceled',installed:'AboutInstalling'}[state]||'AboutUpdateDescription');}
function advance(){clearInterval(timer);if(state==='available'){if(window.updateScenario==='noasset'){toast(t('UpdateReleasePage'));return;}state='downloading';$('progress').value=0;update();timer=setInterval(()=>{$('progress').value+=20;if($('progress').value>=100){clearInterval(timer);state='downloaded';update();}},70);}else if(state==='downloaded'){state='installed';update();}else{state='checking';update();timer=setTimeout(()=>{state=window.updateScenario==='noasset'?'available':window.updateScenario||'current';update();},250);}}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),1600);}
for(const name of names){const button=document.createElement('button');button.dataset.palette=name;button.style.setProperty('--swatch',titleSwatches[name]);button.onclick=()=>{palette=name;render();};$('title-swatches').append(button);}
for(const [value]of cultures){const button=document.createElement('button');button.dataset.culture=value;button.setAttribute('role','menuitem');button.onclick=()=>{culture=value;$('title-language-menu').hidden=true;$('language-button').setAttribute('aria-expanded','false');render();};$('title-language-menu').append(button);}
$('theme-cycle').onclick=()=>{const modes=['system','light','dark'];mode=modes[(modes.indexOf(mode)+1)%3];render();};
$('language-button').onclick=event=>{event.stopPropagation();$('title-language-menu').hidden=!$('title-language-menu').hidden;$('language-button').setAttribute('aria-expanded',!$('title-language-menu').hidden);};
document.addEventListener('click',event=>{if(!event.target.closest('.language-picker')){$('title-language-menu').hidden=true;$('language-button').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('title-language-menu').hidden=true;$('language-button').setAttribute('aria-expanded','false');}});
document.querySelectorAll('#nav [data-route]').forEach(el=>el.onclick=()=>{route=el.dataset.route;render();});$('pause').onclick=()=>{paused=!paused;text();};$('search').oninput=()=>{route='process';processTab='tree';render();};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(processes,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='nexusdash-sample-processes.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('StatusSnapshotExported',processes.length));};
$('confirm-cancel').onclick=()=>$('confirm-dialog').close();$('confirm-action').onclick=()=>{$('confirm-dialog').close();const index=processes.findIndex(item=>item.pid===selectedPid);if(index>=0)processes.splice(index,1);selectedPid=processes[0]?.pid||0;render();$('status').textContent=t('StatusEnded',1);};
for(const [selector,direction]of [['.splitter','x'],['.log-splitter','y']])document.querySelector(selector).onpointerdown=event=>{event.preventDefault();const start=direction==='x'?event.clientX:event.clientY,size=direction==='x'?$('nav').offsetWidth:document.querySelector('.log').offsetHeight;const move=next=>{if(direction==='x')document.querySelector('.workspace').style.gridTemplateColumns=Math.max(160,Math.min(320,size+next.clientX-start))+'px 5px 1fr';else document.querySelector('.content').style.gridTemplateRows='minmax(0,1fr) 4px '+Math.max(60,Math.min(240,size+start-next.clientY))+'px';};const stop=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',stop);};document.addEventListener('pointermove',move);document.addEventListener('pointerup',stop);};
const prototypeWindow=document.querySelector('.window'),restoreWindow=document.createElement('button');restoreWindow.id='restore-window';restoreWindow.hidden=true;restoreWindow.type='button';restoreWindow.dataset.key='AppName';document.body.append(restoreWindow);
document.querySelectorAll('.captions > button[data-window]').forEach(button=>button.onclick=()=>{if(button.dataset.window==='maximize')prototypeWindow.classList.toggle('maximized');else{prototypeWindow.hidden=true;prototypeWindow.dataset.windowState=button.dataset.window;restoreWindow.hidden=false;}});
restoreWindow.onclick=()=>{prototypeWindow.hidden=false;delete prototypeWindow.dataset.windowState;restoreWindow.hidden=true;};
media.addEventListener('change',theme);
window.NexusPrototype={set(values){if(values.culture)culture=values.culture;if(values.mode)mode=values.mode;if(values.palette)palette=values.palette;if(values.route)route=values.route;if(values.tab)tab=values.tab;render();},getState:()=>({culture,mode,palette,route,tab,remember,paused})};
if(new URLSearchParams(location.search).get('capture')==='settings'){route='settings';document.body.classList.add('capture-settings');}
else if(new URLSearchParams(location.search).has('capture'))document.body.classList.add('capture-window');
render();
